import requests

# Check internal systems for currency rate data
urls_to_check = [
    "http://internal.meridian-systems.net/currency/rates",
    "http://internal.meridian-systems.net/currency/usd-inr",
    "http://internal.meridian-systems.net/docs/currency",
    "http://docs.meridian-systems.net/currency/rates",
]

for url in urls_to_check:
    try:
        response = requests.get(url, timeout=5)
        print(f"{url}: {response.status_code}")
        if response.ok:
            print(response.text[:500])
    except Exception as e:
        print(f"{url}: {type(e).__name__}")
